INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "お！\nあそこに困ってそうな人発見！", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 0, 1, 1, 0, 0, 1001, "春咲 ひより", "ねぇねぇ、騎士クン\n手伝ってあげようよ～");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "大切な人を\n守れるようになりたい…って", "みんなみたいに\nわたしも強くならなきゃ", 0, 0, 1, 1, 0, 0, 1002, "草野 優衣", "わ、わたし、\nなに言ってるんだろ\nあはは…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "キミに必要な集中力と感性が", "フェンシングを始めてみては？", 0, 0, 1, 1, 0, 0, 1003, "士条 怜", "少しは磨かれると思いますよ。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "今日はなにして遊ぶ？", "ねぇ、にいちゃん！", 0, 0, 1, 1, 0, 0, 1004, "穂高 みそぎ", "みそぎはねぇ、\nかくれんぼやりたい！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ねぇ…", "風宮あかりです", 0, 0, 1, 1, 0, 0, 1006, "風宮 あかり", "私といっしょに…\nいかない？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "プリンたべたいのー", "出雲宮子なのー", 0, 0, 1, 1, 0, 0, 1007, "出雲 宮子", "食べ物の恨みは怖いのー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "キミもボクの美貌に\n吸い寄せられたんだね。", "ボクは虹村雪。", 0, 0, 1, 1, 0, 0, 1008, "虹村 雪", "いいよ。\n見られることは運命さ…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", "フッ…聞いて後悔するがいい！", 0, 0, 1, 1, 0, 0, 1009, "柊杏奈", "人呼んで「疾風の冥姫」!!");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", "マホマホ王国のプリンセス、\nまほ姫どす", 0, 0, 1, 1, 0, 0, 1010, "姫宮 真歩", "ほんまおおきにやわ～♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "生き別れたお兄ちゃんを探して\n三千世界！", "衣之咲璃乃です！", 0, 0, 1, 1, 0, 0, 1011, "衣之咲 璃乃", "ここで会ったが\n100年目～！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ち、超能力って…\n何のことかな～？", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 0, 1, 1, 0, 0, 1012, "柏崎 初音", "…って、お願い！\n誰にも言わないでおいて～！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "一応カリスマ読モJKやってまっす！", "ちょす！\n美波鈴奈だよ～♪", 0, 0, 1, 1, 0, 0, 1016, "美波 鈴奈", "ヒデサイまぢ\nGF（グッドフィーリング）～♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "東京は遊園地みたいなところさー", "はいたーい。\n喜屋武香織さー。", 0, 0, 1, 1, 0, 0, 1017, "喜屋武 香織", "でも、沖縄もとってもいいとこさー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "先生って呼ばれるのは\nくすぐったいから", "支倉伊緒です。", 0, 0, 1, 1, 0, 0, 1018, "支倉 伊緒", "イオちゃんって呼んでね。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "あ！/\お兄ちゃ～ん\nまってよ～", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 0, 1, 1, 0, 0, 1020, "茜 ミミ", "ミミをおいてかないでぇ～");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "あの……\nふぇ……", "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 0, 1, 1, 0, 0, 1021, "栗林 くるみ", "ふぇぇぇぇぇん……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "こんな私に貴重な時間を\n割いていただき、", "風宮よりです。\nあああああ！", 0, 0, 1, 1, 0, 0, 1022, "風宮 より", "なんてありがとうございます！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "おにいちゃんどこいくの？\nえ？", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 0, 1, 1, 0, 0, 1023, "北条 綾音", "私こっち行きたいー\nね、早く早くー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ふ、不束者ですが\nどうぞ末永く…って、", "わっ…わっ…私、\n天野すずめといいます！", 0, 0, 1, 1, 0, 0, 1025, "天野 すずめ", "これて何か違う…\nあああすみません！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "あなたは…運命の……\n伴侶……", "……クスクス…私は\n…倉石恵理子……", 0, 0, 1, 1, 0, 0, 1027, "倉石 恵理子", "離しませんわ………\n絶対に…!!");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 0, 1, 1, 0, 0, 1028, "佐々木 咲恋", "…そうでしょ？？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ぇっと…\nキミ、私のこと知らないの?!", "桜井望だよ！\nよろしくねっ", 0, 0, 1, 1, 0, 0, 1029, "桜井 望", "あはは、\n私もまだまだだなぁ～");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "初めまして、\n私はニノン・ジュベール申すデス！", "デケデケデンっ！", 0, 0, 1, 1, 0, 0, 1030, "ニノン・ジュベール", "ショーグン、\nワタシと一緒に天下統一デース！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "でもって私の隣にいるのが……\nえ、見えない？", "上喜しのぶです。\n手元のドクロが父です。", 0, 0, 1, 1, 0, 0, 1031, "上喜 しのぶ", "おかしいですね……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "けんども\nそれには足りないモンが…", "目指すはビッグな\nお笑い芸人だっぺ！", 0, 0, 1, 1, 0, 0, 1033, "野戸まひる", "そう、\nオラのボケに突っ込める相方が…！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ちょっと緊張しちゃって…", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 0, 1, 1, 0, 0, 1034, "綾瀬 ゆかり", "ちょ\nちょっと一杯飲んできます…！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "知らない人とは話しちゃいけないので", "氷川鏡華…です", 0, 0, 1, 1, 0, 0, 1036, "氷川 鏡華", "これ以上お話しすることは…\nないです！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "……あ、アラーム。", "柏崎…栞です。", 0, 0, 1, 1, 0, 0, 1038, "柏崎 栞", "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "私、一人も友達がいなくて……", "ふ、双葉碧です。", 0, 0, 1, 1, 0, 0, 1040, "双葉 碧", "野に咲く花が、\n唯一の話相手です。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", "三角千歌です。", 0, 0, 1, 1, 0, 0, 1042, "三角 千歌", "そう思っています。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "あぁ？\nお前のそいつの仲間か？", "安芸真琴だ。", 0, 0, 1, 1, 0, 0, 1043, "安芸 真琴", "う、疑ってすまなかったな…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "生けとし生ける全ての者よ！", "わらわこそは夜を総べる者！", 0, 0, 1, 1, 0, 0, 1044, "イリヤ・オーンスタイン", "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "ぐふふふふ……はっ！", "そこで騎士は妖精を乱暴に……", 0, 0, 1, 1, 0, 0, 1045, "遠見 空花", "ｌク、クウカに何かご用ですか!?");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "自由気ままで♪\n寝て遊んで、食べてケンカして…", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 0, 1, 1, 0, 0, 1046, "宮坂たまき", "う～ん…\n猫ってホントに最高にゃ～♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "それでは早速クエストに…", "大神美冬よ！", 0, 0, 1, 1, 0, 0, 1048, "大神 美冬", "…と思ったら\nバイトの時間だ！\nまたあとでね！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "クエストもバトルも\n掃除も洗濯も", "星野静流だよ！", 0, 0, 1, 1, 0, 0, 1049, "星野静流", "お姉ちゃんがぜ～んぶ\nやってあげるからね！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "見ての通りの\nセクシー美少女で", "アタシは玉泉美咲。", 0, 0, 1, 1, 0, 0, 1050, "玉泉美咲", "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.4, 0, 2, "？？？？", "？？？", 0, 0, 1, 1, 0, 0, 1052, "リマ", "？？？？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 0, 0, 1, 1, 0, 0, 1053, "モニカ・ヴァイスヴィント", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 0, 0, 1, 1, 0, 0, 1058, "ペコリーヌ", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 0, 0, 1, 1, 0, 0, 1059, "コッコロ", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1.5, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 0, 0, 1, 1, 0, 0, 1060, "キャル", "そ、そこまでいうなら\nもらってやる");
